<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();$vid=(int)($_GET['vehiculo_id']??$_POST['vehiculo_id']??0);$cid=(int)($_GET['id']??$_POST['cotizacion_id']??0);$cot=$cid?srnu_obtener_cotizacion($cid):null;
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['guardar'])){$data=[epost('cliente'),epost('telefono'),epost('descripcion'),epost('placas'),epost('vin'),epost('kilometraje'),epost('color'),epost('notas')];if($vid){$pdo->prepare('UPDATE vehiculos SET cliente=?,telefono=?,descripcion=?,placas=?,vin=?,kilometraje=?,color=?,notas=? WHERE id=?')->execute([...$data,$vid]);}else{$pdo->prepare('INSERT INTO vehiculos(cliente,telefono,descripcion,placas,vin,kilometraje,color,notas) VALUES(?,?,?,?,?,?,?,?)')->execute($data);$vid=(int)$pdo->lastInsertId();}if($cid)$pdo->prepare('UPDATE cotizaciones SET vehiculo_id=? WHERE id=?')->execute([$vid,$cid]);ego('expediente.php?vehiculo_id='.$vid);}
if(!$vid&&$cot){if(!empty($cot['vehiculo_id']))$vid=(int)$cot['vehiculo_id'];}
$v=null;if($vid){$s=$pdo->prepare('SELECT * FROM vehiculos WHERE id=?');$s->execute([$vid]);$v=$s->fetch()?:null;}
if(!$v&&$cot)$v=['cliente'=>$cot['cliente'],'telefono'=>$cot['telefono'],'descripcion'=>$cot['vehiculo'],'placas'=>'','vin'=>'','kilometraje'=>'','color'=>'','notas'=>''];if(!$v){http_response_code(404);exit('Indica una cotización o expediente.');}
$quotes=[];$payments=[];$gar=[];$photos=[];if($vid){$s=$pdo->prepare('SELECT * FROM cotizaciones WHERE vehiculo_id=? ORDER BY fecha DESC,id DESC');$s->execute([$vid]);$quotes=$s->fetchAll();if($quotes){$ids=array_column($quotes,'id');$ph=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT p.*,c.folio FROM pagos p JOIN cotizaciones c ON c.id=p.cotizacion_id WHERE p.cotizacion_id IN ($ph) ORDER BY p.fecha DESC");$s->execute($ids);$payments=$s->fetchAll();$s=$pdo->prepare("SELECT g.*,c.folio FROM garantias g JOIN cotizaciones c ON c.id=g.cotizacion_id WHERE g.cotizacion_id IN ($ph) ORDER BY g.fecha_fin DESC");$s->execute($ids);$gar=$s->fetchAll();$s=$pdo->prepare("SELECT gt.*,c.folio FROM galeria_trabajos gt JOIN cotizaciones c ON c.id=gt.cotizacion_id WHERE gt.cotizacion_id IN ($ph) ORDER BY gt.id DESC LIMIT 18");$s->execute($ids);$photos=$s->fetchAll();}}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Expediente · SRNU</title><?=srnu_ui_head()?></head><body><?php srnu_appbar('cotizaciones');?><main class="w"><div class="srnu-page-heading"><div><h1>Expediente del vehículo</h1><p>Historial técnico y comercial permanente.</p></div><a class="btn light" href="vehiculos.php">Todos los vehículos</a></div><section class="panel" style="padding:18px"><form method="post" class="erp-form cols-4"><input type="hidden" name="vehiculo_id" value="<?=$vid?>"><input type="hidden" name="cotizacion_id" value="<?=$cid?>"><input name="cliente" required placeholder="Cliente" value="<?=eh($v['cliente'])?>"><input name="telefono" placeholder="Teléfono" value="<?=eh($v['telefono'])?>"><input name="descripcion" required placeholder="Vehículo" value="<?=eh($v['descripcion'])?>"><input name="color" placeholder="Color" value="<?=eh($v['color'])?>"><input name="placas" placeholder="Placas" value="<?=eh($v['placas'])?>"><input name="vin" placeholder="VIN" value="<?=eh($v['vin'])?>"><input name="kilometraje" placeholder="Kilometraje actual" value="<?=eh($v['kilometraje'])?>"><input name="notas" placeholder="Notas permanentes" value="<?=eh($v['notas'])?>"><button class="btn blue" name="guardar" value="1">Guardar expediente</button></form></section><?php if($vid):?><div class="grid-2" style="margin-top:16px"><section class="panel" style="padding:18px"><h3>Trabajos / cotizaciones</h3><table><tr><th>Folio</th><th>Fecha</th><th>Estado</th><th>Total</th></tr><?php foreach($quotes as $r):?><tr><td><a href="cotizador.php?id=<?=$r['id']?>"><?=eh($r['folio'])?></a></td><td><?=edate($r['fecha'])?></td><td><?=eh($r['estado'])?></td><td><?=emoney($r['total'])?></td></tr><?php endforeach;?></table></section><section class="panel" style="padding:18px"><h3>Pagos</h3><table><tr><th>Fecha</th><th>Folio</th><th>Destino</th><th>Monto</th></tr><?php foreach($payments as $r):?><tr><td><?=edate($r['fecha'])?></td><td><?=eh($r['folio'])?></td><td><?=eh($r['destinatario'])?></td><td><?=emoney($r['monto'])?></td></tr><?php endforeach;?></table></section></div><section class="panel" style="padding:18px;margin-top:16px"><h3>Garantías</h3><table><tr><th>Folio</th><th>Concepto</th><th>Inicio</th><th>Vence</th><th>Estado</th></tr><?php foreach($gar as $r):?><tr><td><?=eh($r['folio'])?></td><td><?=eh($r['concepto'])?></td><td><?=edate($r['fecha_inicio'])?></td><td><?=edate($r['fecha_fin'])?></td><td><?=eh($r['estado'])?></td></tr><?php endforeach;?></table></section><?php if($photos):?><section class="panel" style="padding:18px;margin-top:16px"><h3>Galería reciente</h3><div class="photo-grid"><?php foreach($photos as $p):?><div class="photo-card"><img src="galeria_foto.php?id=<?=$p['id']?>"><div><b><?=eh($p['etapa'])?></b><br><span class="muted"><?=eh($p['folio'])?></span></div></div><?php endforeach;?></div></section><?php endif;?><?php endif;?></main></body></html>
